 public sealed partial class MultiLineFactory {
  FullFrameCapture fullFrame;FullState fullState=new FullState{status="Connecting",actual_device="unavailable",counts=new FullCounts(),latest=new FullResult[0]};string fullEndpoint,fullMode="Full-frame vision",fullDevice="cpu";int fullViews=1,fullCursor,fullOffered,fullCaptured,fullSubmitted,fullAccepted,fullDropped,fullSending,fullGeneration,fullPreview=0;double fullHz=5,fullNext,fullNextPoll,fullNextAudit,fullRenderMs,fullReadMs,fullTransportMs;bool fullPolling,fullRegistering;readonly Dictionary<string,double> fullDue=new Dictionary<string,double>();Texture2D fullImage;string fullImageId="";bool fullImageLoading;Dictionary<string,string> fullRegistry=new Dictionary<string,string>();
  void Stage5Init(){fullFrame=new FullFrameCapture();fullEndpoint=Arg("--stage5-endpoint","http://127.0.0.1:8840");if(new Uri(fullEndpoint).Host!="127.0.0.1")throw new Exception("Stage5 loopback only");int v=int.Parse(Arg("--analysis-views","1")),h=int.Parse(Arg("--analysis-hz","5"));fullViews=Array.IndexOf(new[]{1,3,9},v)>=0?v:1;fullHz=Array.IndexOf(new[]{5,10,20},h)>=0?h:5;fullMode=Arg("--full-frame-disabled","false")=="true"?"Established inspection":"Full-frame vision";fullDevice=Arg("--detector-device","cpu");if(visuals.Count>3)Resize(3);ApplyStage5Layers();if(Arg("--dataset-plan","")!=""){paused=true;StartCoroutine(FullDataset(Arg("--dataset-plan")));}}
  void SetLayer(GameObject root,int layer){if(root==null)return;foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=layer;}
  void ApplyStage5Layers(){if(fullFrame==null)return;int mask=(1<<8)|(1<<9)|(1<<10)|(1<<11)|(1<<12)|(1<<13)|(1<<14);if(main!=null)main.cullingMask=mask;if(floor!=null)floor.layer=8;foreach(var light in FindObjectsOfType<Light>(true))if((light.cullingMask&((1<<8)|(1<<9)))!=0)light.cullingMask=mask;for(int i=0;i<visuals.Count&&i<3;i++){int layer=9+i,textLayer=12+i;SetLayer(visuals[i].Geometry.Root,8);SetLayer(visuals[i].Brewery.Root,layer);foreach(var label in visuals[i].Geometry.Root.GetComponentsInChildren<TextMesh>(true))label.gameObject.layer=textLayer;foreach(var sign in visuals[i].Brewery.Root.GetComponentsInChildren<Transform>(true))if(sign.name.Contains("station sign")||sign.name.Contains("product sign"))SetLayer(sign.gameObject,textLayer);}}
  void AcquisitionTrace(string kind,LineVisual line,Bottle bottle,string reason){if(Arg("--trace-acquisition","false")!="true")return;var p=Path.Combine(dataPath,"acquisition-trace.jsonl");if(File.Exists(p)&&new FileInfo(p).Length>4194304)return;File.AppendAllText(p,"{\"event\":\""+kind+"\",\"wall\":"+Wall.ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+",\"line_id\":\""+line.State.Id+"\",\"session_id\":\""+line.State.Adapter.Session+"\",\"bottle_id\":\""+bottle.Id+"\",\"sim_time\":"+line.State.Sim.Time.ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+",\"target_x\":"+bottle.X.ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+",\"remaining_lifetime_known\":false,\"target_exists\":"+(line.State.Sim.Bottles.Contains(bottle)?"true":"false")+",\"age_ms\":"+(1000*(Wall-line.PendingAt)).ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+",\"reason\":\""+reason.Replace("\"","'")+"\"}\n");}
  void Stage5Tick(){if(fullFrame==null||Arg("--dataset-plan","")!="")return;bool changed=fullRegistry.Count!=Math.Min(3,visuals.Count);for(int i=0;i<Math.Min(3,visuals.Count)&&!changed;i++){string s;changed=!fullRegistry.TryGetValue(visuals[i].State.Id,out s)||s!=visuals[i].State.Adapter.Session;}if(changed&&!fullRegistering){fullGeneration++;fullDue.Clear();fullImageId="";if(fullImage!=null)Destroy(fullImage);fullImage=null;StartCoroutine(FullRegister());}
   if(Wall>fullNextPoll&&!fullPolling){fullNextPoll=Wall+.5;StartCoroutine(FullPoll());}if(Wall>fullNextAudit){fullNextAudit=Wall+.5;var native=FullReport();File.WriteAllText(Path.Combine(dataPath,"stage5-audit.json"),JsonUtility.ToJson(native));StartCoroutine(FullPostJson("/native",JsonUtility.ToJson(native)));}
   if(fullMode!="Full-frame vision"||paused||fullRegistering||Arg("--dataset-plan","")!="")return;
   int views=Math.Min(fullViews,Math.Min(3,visuals.Count)*3);for(int k=0;k<views;k++){int index=(fullCursor+k)%views;var line=visuals[index/3];string key=line.State.Id+":"+index%3;double due; if(!fullDue.TryGetValue(key,out due))due=Wall;if(Wall<due)continue;fullDue[key]=Wall+1/fullHz;fullOffered++;fullCursor=(index+1)%views;
    if(fullSending>=6){fullDropped++;FullTrace("dropped",null,"http-capacity",line.State.Id);continue;}
    int generation=fullGeneration;bool requested=fullFrame.Request(line,index%3,packet=>{if(packet.Error!=null){fullDropped++;FullTrace("dropped",packet,packet.Error);return;}if(generation!=fullGeneration){fullDropped++;FullTrace("dropped",packet,"retired-readback");return;}fullCaptured++;fullRenderMs=packet.RenderMs;fullReadMs=packet.ReadbackMs;FullTrace("captured",packet,"");StartCoroutine(FullSend(packet,generation));});
    if(!requested){fullDropped++;FullTrace("dropped",null,fullFrame.AsyncSupported?"readback-ring-full":"async-unavailable",line.State.Id);}break;
   }
  }
  IEnumerator FullRegister(){fullRegistering=true;fullRegistry.Clear();var lines=new List<MultiRegistryLine>();for(int i=0;i<Math.Min(3,visuals.Count);i++){var l=visuals[i];fullRegistry[l.State.Id]=l.State.Adapter.Session;lines.Add(new MultiRegistryLine{line_id=l.State.Id,session_id=l.State.Adapter.Session});}yield return FullPostJson("/registry",JsonUtility.ToJson(new MultiRegistry{lines=lines.ToArray()}));yield return FullPostJson("/device","{\"device\":\""+fullDevice+"\"}");fullRegistering=false;}
  UnityWebRequest FullPost(string path,byte[] body){var r=new UnityWebRequest(fullEndpoint+path,"POST"){uploadHandler=new UploadHandlerRaw(body),downloadHandler=new DownloadHandlerBuffer()};r.timeout=3;return r;}
  IEnumerator FullPostJson(string path,string body){using(var r=FullPost(path,Encoding.UTF8.GetBytes(body))){r.SetRequestHeader("Content-Type","application/json");yield return r.SendWebRequest();if(r.result!=UnityWebRequest.Result.Success)notice="Full-frame request unavailable: "+r.downloadHandler.text;}}
  IEnumerator FullSend(FullFramePacket packet,int generation){fullSending++;fullSubmitted++;double at=Wall;using(var r=FullPost("/frame",packet.Pixels)){r.SetRequestHeader("Content-Type","image/png");r.SetRequestHeader("X-Gts-Metadata",JsonUtility.ToJson(packet.Metadata));yield return r.SendWebRequest();fullTransportMs=(Wall-at)*1000;if(r.result==UnityWebRequest.Result.Success&&generation==fullGeneration){fullAccepted++;FullTrace("accepted",packet,"");}else{fullDropped++;FullTrace("dropped",packet,generation!=fullGeneration?"retired-http":"http-rejection:"+r.downloadHandler.text);}}fullSending--;}
  void FullTrace(string kind,FullFramePacket packet,string reason,string line=""){string p=Path.Combine(dataPath,"full-captures.jsonl");if(File.Exists(p)&&new FileInfo(p).Length>4194304){string old=p+".1";if(File.Exists(old))File.Delete(old);File.Move(p,old);}var body=packet==null?"null":JsonUtility.ToJson(packet.Metadata);File.AppendAllText(p,"{\"event\":\""+kind+"\",\"wall_epoch\":"+((DateTime.UtcNow-new DateTime(1970,1,1)).TotalSeconds).ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+",\"metadata\":"+body+",\"line\":\""+line+"\",\"reason\":\""+reason.Replace("\"","'").Replace("\n"," ").Replace("\r"," ")+"\",\"readback_ms\":"+(packet==null?0:packet.ReadbackMs).ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+",\"render_ms\":"+(packet==null?0:packet.RenderMs).ToString("F6",System.Globalization.CultureInfo.InvariantCulture)+"}\n");}
  IEnumerator FullPoll(){fullPolling=true;using(var r=UnityWebRequest.Get(fullEndpoint+"/state")){r.timeout=2;yield return r.SendWebRequest();if(r.result==UnityWebRequest.Result.Success){fullState=JsonUtility.FromJson<FullState>(r.downloadHandler.text);var result=CurrentFull();if(result!=null&&!fullImageLoading&&result.metadata.frame_id!=fullImageId)StartCoroutine(FullLoad(result));}else{fullState.status="unavailable";fullState.actual_device="unavailable";fullState.latest=new FullResult[0];fullRegistry.Clear();}}fullPolling=false;}
  FullResult CurrentFull(){if(fullState.latest!=null)foreach(var r in fullState.latest)if(r.metadata.line_id==Selected.State.Id&&r.metadata.session_id==Selected.State.Adapter.Session&&r.metadata.camera_id=="View"+(fullPreview+1))return r;return null;}
  IEnumerator FullLoad(FullResult result){fullImageLoading=true;using(var r=UnityWebRequest.Get(fullEndpoint+result.overlay_url)){r.timeout=2;yield return r.SendWebRequest();if(r.result==UnityWebRequest.Result.Success&&result.metadata.session_id==Selected.State.Adapter.Session){var texture=new Texture2D(2,2,TextureFormat.RGBA32,false);if(texture.LoadImage(r.downloadHandler.data)){if(fullImage!=null)Destroy(fullImage);fullImage=texture;fullImageId=result.metadata.frame_id;}else Destroy(texture);}}fullImageLoading=false;}
  FullNative FullReport(){return new FullNative{mode=fullMode,readback_backend=fullFrame.Backend,session_id=Selected.State.Adapter.Session,pid=Process.GetCurrentProcess().Id,paused=paused,async_supported=fullFrame.AsyncSupported,views=Math.Min(fullViews,Math.Min(3,visuals.Count)*3),offered=fullOffered,captured=fullCaptured,submitted=fullSubmitted,accepted=fullAccepted,dropped=fullDropped,pending=fullSending+fullFrame.Busy,generation=fullGeneration,configured_hz=fullHz,wall_seconds=Wall-started,frame_p50_ms=fp50,frame_p95_ms=fp95,frame_p99_ms=fp99,fps=frameTimes.Count/Math.Max(.001,SumFrames()/1000),camera_render_ms=fullRenderMs,readback_ms=fullReadMs,transport_ms=fullTransportMs,selected_device=fullDevice};}
