   if(view=="Full-frame"){Panel(new Rect(230,175,1320,845));GUI.Label(new Rect(252,190,1250,50),"Full frame — detector boxes / image track IDs / proposed regions",title);if(fullImage!=null)GUI.DrawTexture(new Rect(250,251,640,640),fullImage,ScaleMode.ScaleToFit);GUI.Label(new Rect(925,260,590,530),result==null?"Waiting for camera evidence":result.metadata.line_id+" / "+result.metadata.camera_id+"\nFrame "+result.metadata.frame_id+"\nCapture "+result.metadata.capture_utc+"\nImage tracks are NOT simulator bottle IDs\n"+result.detections.Length+" detections\nCapture→result "+result.end_to_end_ms.ToString("0.0")+"ms\nInference(completed) "+result.timing.inference_completed_ms.ToString("0.0")+"ms\n"+result.downstream+"\nPixels cannot establish torque, seal, volume or cause.",text);}
